rep("    // One Gaode basemap only, using the same raster source as the reference app.\n    // No provider switch, SDK or API key needed for this view. Tiles may still\n    // be subject to provider-side rate limiting and access policies.\n    map.eachLayer(layer=>{if(layer instanceof L.TileLayer)map.removeLayer(layer);});\n    const rasterLayer=createReferenceRasterLayer(L,'amap');", "    // Day = reference Gaode raster, night = OSM raster with a local dark style.\n    // No unlicensed CARTO dark tile endpoints or API-key bypasses.\n    // Night uses ORIGINAL WGS84 geographic points, not Gaode's GCJ-02.\n    map.eachLayer(layer=>{if(layer instanceof L.TileLayer)map.removeLayer(layer);});\n    const rasterLayer=basemap==='amap'?createReferenceRasterLayer(L,'amap'):\n      L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{\n        minZoom:1,maxZoom:19,tileSize:256,keepBuffer:3,className:'tn-osm-night-tiles',\n        attribution:'© OpenStreetMap contributors'\n      });")
